#!/bin/sh
# Generated by forge. PostToolUse(Edit|Write): formats the edited file silently,
# lints it and runs the ast-grep forbid rules on it. Findings go back to Claude
# as additionalContext (<= 20 lines). Nothing on success.
dir=$(cd "$(dirname "$0")" && pwd)
FORGE_INPUT=$(cat)
. "$dir/lib.sh"
repo_root || exit 0
file=$(json_get file_path)
[ -n "$file" ] || exit 0
file=$(rel_path "$file") || exit 0
[ -f "$file" ] || exit 0
case $file in .forge/*|.claude/*|.git/*|node_modules/*|.venv/*) exit 0 ;; esac
IFS='
'
FORGE_TMP=$(mktemp -d "${TMPDIR:-/tmp}/forge-edit.XXXXXX") || exit 0
trap 'rm -rf "$FORGE_TMP"' EXIT HUP INT TERM

@@CHECKS@@

FORGE_FORBID='@@FORBID@@'

forge_file_stage format "$file" > /dev/null 2>&1
forge_file_stage lint "$file" > "$FORGE_TMP/report" 2>&1
if [ -n "$FORGE_FORBID" ] && [ -f .forge/ast-grep/sgconfig.yml ]; then
  astgrep scan -c .forge/ast-grep/sgconfig.yml --filter "^($FORGE_FORBID)\$" --report-style short "$file" 2>/dev/null \
    | grep -E '^[^[:space:]]+:[0-9]+:[0-9]+: ' \
    | sed -E 's/^([^[:space:]]+:[0-9]+:[0-9]+): [a-z]+\[[^]]*\]: forge:([^[:space:]]+) (.*)$/forge:\2 \1 \3/' >> "$FORGE_TMP/report"
fi
[ -s "$FORGE_TMP/report" ] || exit 0
ctx=$(first_lines 20 < "$FORGE_TMP/report" | json_escape)
printf '{"hookSpecificOutput":{"hookEventName":"PostToolUse","additionalContext":"%s"}}\n' "$ctx"
exit 0
